    B_block_ptr = tl.make_block_ptr(B, shape=(K,N), strides=(stride_bk, stride_bn), order=(0,1))
    for k in range(K//BLOCK_K):
        b = tl.load(B_block_ptr, boundary_check=(0,1))  # no tl.trans
        acc += tl.dot(a, b)
        B_block_ptr = tl.advance(B_block_ptr, (BLOCK_K, 0))

